import {
  SOURCE,
  acceptLanguages,
  pick,
  translator,
  type Messages,
  type Vars,
} from '../../src/i18n/core';
// Generated by tools/i18n.mjs from the `server` part of every language file.
import catalogue from './messages.generated.json';

// The server's messages in the learner's language (docs/i18n.md). The app sends its language
// as `x-nl-lang`; anything else falls back to Accept-Language, then Arabic.

const all = catalogue as unknown as Record<string, Messages>;
export const SERVER_LOCALES = Object.keys(all);

/** The language a request asked for. */
export function localeOf(request: Request): string {
  return (
    pick(
      [
        request.headers.get('x-nl-lang') ?? '',
        ...acceptLanguages(request.headers.get('accept-language')),
      ],
      SERVER_LOCALES,
    ) ?? SOURCE
  );
}

/** A server message (a key under `server.` in the language files) in a language. */
export function serverText(locale: string, key: string, vars?: Vars): string {
  return translator(locale, all[locale] ?? {}, all[SOURCE])(key, vars);
}

/** The English name of a language, for model instructions ("Reply in French"). */
export function languageInEnglish(code: string): string {
  try {
    return new Intl.DisplayNames(['en'], { type: 'language' }).of(code) ?? code;
  } catch {
    return code;
  }
}
